CREATE TABLE `projects` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned DEFAULT NULL,
  `url` varchar(2048) NOT NULL DEFAULT '',
  `created` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `ignore_robotstxt` tinyint NOT NULL DEFAULT '0',
  `follow_nofollow` tinyint NOT NULL DEFAULT '0',
  `include_noindex` tinyint NOT NULL DEFAULT '0',
  `crawl_sitemap` tinyint NOT NULL DEFAULT '0',
  `allow_subdomains` tinyint NOT NULL DEFAULT '0',
  `deleting` tinyint NOT NULL DEFAULT '0',
  `basic_auth` tinyint NOT NULL DEFAULT '0',
  `check_external_links` tinyint NOT NULL DEFAULT '0',
  `archive` tinyint NOT NULL DEFAULT '0',
  `user_agent` varchar(500) NOT NULL DEFAULT 'Mozilla/5.0 (compatible; SEOnautBot/1.0; +https://seonaut.org/bot)',
  `schedule_interval` varchar(16) NOT NULL DEFAULT '',
  `next_run` timestamp NULL DEFAULT NULL,
  `webhook_url` varchar(2048) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `projects_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
